import sys

def solve_case(n, b):
    # preMax[i] 和 preMin[i] 分别表示 b[1..i] 的最大值和最小值，i从1开始
    preMax = [0] * (n + 1)
    preMin = [0] * (n + 1)
    cur_max = -10**19
    cur_min = 10**19
    # 遍历奖励数组 b[0..n-2]，对应原始位置的 b_1..b_{n-1}
    for i in range(1, n):
        val = b[i - 1]
        if val > cur_max:
            cur_max = val
        if val < cur_min:
            cur_min = val
        preMax[i] = cur_max
        preMin[i] = cur_min

    max_sum = 0
    min_sum = 0
    # 步数：依次取前缀右端点 n-1, n-3, ..., 直到 ≥1
    r = n - 1
    while r >= 1:
        max_sum += preMax[r]
        min_sum += preMin[r]
        r -= 2
    return max_sum, min_sum

def main():
